public String sortString(String s) {
    int[] cnt = new int[26];
    for(char c: s.toCharArray()) cnt[c-'a']++;

    StringBuilder sb = new StringBuilder();
    while(sb.length() < s.length()){
        // ascending
        for(int i=0;i<26;i++){
            if(cnt[i]>0){
                sb.append((char)(i+'a'));
                cnt[i]--;
                // continue to pick next greater
                for(int j=i+1;j<26;j++){
                    if(cnt[j]>0){
                        sb.append((char)(j+'a'));
                        cnt[j]--;
                        i=j; // update i to last added
                    }
                }
                // After finishing ascending loop, break to start descending
                break;
            }
        }
        // descending
        for(int i=25;i>=0;i--){
            if(cnt[i]>0){
                sb.append((char)(i+'a'));
                cnt[i]--;
                for(int j=i-1;j>=0;j--){
                    if(cnt[j]>0){
                        sb.append((char)(j+'a'));
                        cnt[j]--;
                        i=j;
                    }
                }
                break;
            }
        }
    }
    return sb.toString();
}

