public String sortString(String s) {
    int[] freq = new int[256];
    for (char c: s.toCharArray()) freq[c]++;
    StringBuilder res = new StringBuilder();
    int total = s.length();
    while (res.length() < total) {
        // ascending part
        char last = 0;
        // find first smallest unused char
        for (int i=0; i<freq.length; i++) if (freq[i]>0) { last = (char)i; freq[i]--; res.append(last); break; }
        // continue picking greater
        for (int i=last+1; i<freq.length; i++) {
            while (freq[i]>0 && (char)i > last) {
                last = (char)i;
                freq[i]--;
                res.append(last);
            }
        }
        if (res.length() >= total) break;
        // descending part
        // find largest unused char
        int largestIndex = freq.length -1;
        while (largestIndex>=0 && freq[largestIndex]==0) largestIndex--;
        if (largestIndex<0) break; // no more
        char lastChar = (char)largestIndex;
        freq[largestIndex]--;
        res.append(lastChar);
        // keep selecting largest less than lastChar
        for (int i=largestIndex-1; i>=0; i--) {
            while (freq[i]>0 && (char)i < lastChar) {
                lastChar = (char)i;
                freq[i]--;
                res.append(lastChar);
            }
        }
    }
    return res.toString();
}

